    /**
     * Method to retrieve the Room via RoomFetchOneSummary
     * @param 	summary RoomFetchOneSummary 
     * @return 	RoomFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Room getRoom( RoomFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "RoomFetchOneSummary arg cannot be null" );
    	
    	Room entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Room
        	// --------------------------------------
        	CompletableFuture<Room> futureEntity = queryGateway.query(new FindRoomQuery( new LoadRoomFilter( summary.getRoomId() ) ), ResponseTypes.instanceOf(Room.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Room with id " + summary.getRoomId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


